{
  "id": "beer-distribution-game-cla",
  "name": "Beer Distribution Game",
  "description": "The classic 'Beer Game' supply chain simulation developed at MIT Sloan. Demonstrates the bullwhip effect where small changes in retail demand cause increasingly larger fluctuations at each upstream stage (retailer, wholesaler, distributor, factory). Reference: Based on System Dynamics supply chain models (Sterman, 2000). Source: https://systemdynamics.org/",
  "stocks": [
    {
      "id": "stock-retailer-inventory",
      "name": "Retailer Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-wholesaler-inventory",
      "name": "Wholesaler Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-distributor-inventory",
      "name": "Distributor Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    },
    {
      "id": "stock-factory-inventory",
      "name": "Factory Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 750,
        "y": 200
      }
    },
    {
      "id": "stock-retailer-backlog",
      "name": "Retailer Backlog",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-retailer",
      "name": "Supply Line Retailer",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-wholesaler",
      "name": "Supply Line Wholesaler",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 550,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-distributor",
      "name": "Supply Line Distributor",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 750,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-customer-demand",
      "name": "Customer Demand",
      "equation": "IF Time < 5 THEN 4 ELSE 8",
      "from_stock": null,
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-retailer-orders",
      "name": "Retailer Orders",
      "equation": "MAX(0, Expected_Demand + Inventory_Adjustment_Retailer + Supply_Line_Adjustment_Retailer)",
      "from_stock": null,
      "to_stock": "stock-supply-line-retailer",
      "position": {
        "x": 450,
        "y": 200
      }
    },
    {
      "id": "flow-wholesaler-orders",
      "name": "Wholesaler Orders",
      "equation": "MAX(0, Retailer_Orders + Inventory_Adjustment_Wholesaler + Supply_Line_Adjustment_Wholesaler)",
      "from_stock": null,
      "to_stock": "stock-supply-line-wholesaler",
      "position": {
        "x": 650,
        "y": 200
      }
    },
    {
      "id": "flow-distributor-orders",
      "name": "Distributor Orders",
      "equation": "MAX(0, Wholesaler_Orders + Inventory_Adjustment_Distributor + Supply_Line_Adjustment_Distributor)",
      "from_stock": null,
      "to_stock": "stock-supply-line-distributor",
      "position": {
        "x": 250,
        "y": 350
      }
    },
    {
      "id": "flow-production",
      "name": "Production",
      "equation": "DELAY3(Production_Order, Production_Delay)",
      "from_stock": null,
      "to_stock": "stock-factory-inventory",
      "position": {
        "x": 450,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "var-shipping-delay",
      "name": "Shipping Delay",
      "equation": "2",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-production-delay",
      "name": "Production Delay",
      "equation": "3",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-desired-inventory",
      "name": "Desired Inventory",
      "equation": "12",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-inventory-adjustment-time",
      "name": "Inventory Adjustment Time",
      "equation": "4",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-expected-demand",
      "name": "Expected Demand",
      "equation": "SMOOTH(Customer_Demand, Demand_Forecast_Time)",
      "position": {
        "x": 700,
        "y": 80
      }
    },
    {
      "id": "var-demand-forecast-time",
      "name": "Demand Forecast Time",
      "equation": "4",
      "position": {
        "x": 100,
        "y": 160
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Customer Demand",
      "to_element": "retailer_shipments"
    },
    {
      "id": "conn-2",
      "from_element": "Retailer Orders",
      "to_element": "Supply Line Retailer"
    },
    {
      "id": "conn-3",
      "from_element": "Wholesaler Orders",
      "to_element": "Supply Line Wholesaler"
    },
    {
      "id": "conn-4",
      "from_element": "Distributor Orders",
      "to_element": "Supply Line Distributor"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 52,
    "dt": 1
  },
  "created_at": "2026-01-11T20:04:50.689151Z",
  "updated_at": "2026-01-11T20:04:50.689151Z",
  "source": "https://doi.org/10.1287/mnsc.35.3.321",
  "reference": "Sterman JD. Business Dynamics: Systems Thinking and Modeling for a Complex World. McGraw-Hill, 2000."
}

{
  "id": "world3-non-renewable-resources-sector-cla",
  "name": "World3 Non-Renewable Resources Sector",
  "description": "The non-renewable resource dynamics sector from the World3 model. Models resource extraction, depletion, and the effect of declining resource availability on the economy. Reference: IRENA Renewable Energy Statistics. Source: https://www.irena.org/",
  "stocks": [
    {
      "id": "stock-non-renewable-resources",
      "name": "Non-Renewable Resources",
      "initial_value": 1000000000000.0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-resource-usage-rate",
      "name": "Resource Usage Rate",
      "equation": "Population * Per_Capita_Resource_Usage * Resource_Usage_Multiplier",
      "from_stock": "stock-non-renewable-resources",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 200
      }
    }
  ],
  "variables": [
    {
      "id": "var-population",
      "name": "Population",
      "equation": "3e9",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-per-capita-resource-usage",
      "name": "Per Capita Resource Usage",
      "equation": "1",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-resource-usage-multiplier",
      "name": "Resource Usage Multiplier",
      "equation": "Resource_Usage_From_Industry(Industrial_Output_Per_Capita)",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-fraction-of-resources-remaining",
      "name": "Fraction of Resources Remaining",
      "equation": "\"Non-Renewable Resources\" / Initial_Resources",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-initial-resources",
      "name": "Initial Resources",
      "equation": "1e12",
      "position": {
        "x": 700,
        "y": 80
      }
    },
    {
      "id": "var-resource-extraction-capital-requirement",
      "name": "Resource Extraction Capital Requirement",
      "equation": "Resource_Extraction_Fraction(Fraction_of_Resources_Remaining)",
      "position": {
        "x": 100,
        "y": 160
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 1900,
    "end": 2100,
    "dt": 1
  },
  "created_at": "2026-01-11T20:04:50.697230Z",
  "updated_at": "2026-01-11T20:04:50.697230Z",
  "source": "https://doi.org/10.1016/B978-0-12-850754-3.50020-2",
  "reference": "Meadows DH, Meadows DL, Randers J, Behrens WW. The Limits to Growth. Universe Books, 1972."
}

{
  "id": "arctic-sea-ice-decline-model-cli",
  "name": "Arctic Sea Ice Decline Model",
  "description": "Model of Arctic sea ice extent decline with ice-albedo feedback and September minimum projections. Reference: Based on project dynamics models (Lyneis & Ford, 2007). Source: https://systemdynamics.org/",
  "stocks": [
    {
      "id": "stock-ice-extent",
      "name": "Ice_Extent",
      "initial_value": 7.0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-ice-volume",
      "name": "Ice_Volume",
      "initial_value": 16.0,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-multi-year-ice",
      "name": "Multi_Year_Ice",
      "initial_value": 3.5,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-ice-melt",
      "name": "ice_melt",
      "equation": "melt_sensitivity * warming_rate * (Ice_Extent + feedback_amplification)",
      "from_stock": "stock-ice-extent",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-ice-formation",
      "name": "ice_formation",
      "equation": "0",
      "from_stock": null,
      "to_stock": "stock-ice-extent",
      "position": {
        "x": 450,
        "y": 200
      }
    },
    {
      "id": "flow-volume-loss",
      "name": "volume_loss",
      "equation": "0",
      "from_stock": "stock-ice-volume",
      "to_stock": null,
      "position": {
        "x": 650,
        "y": 200
      }
    },
    {
      "id": "flow-myi-loss",
      "name": "myi_loss",
      "equation": "0",
      "from_stock": "stock-multi-year-ice",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "var-warming-rate",
      "name": "warming_rate",
      "equation": "0.05",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-melt-sensitivity",
      "name": "melt_sensitivity",
      "equation": "0.15",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-albedo-ice",
      "name": "albedo_ice",
      "equation": "0.6",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-albedo-ocean",
      "name": "albedo_ocean",
      "equation": "0.06",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-ice-free-threshold",
      "name": "ice_free_threshold",
      "equation": "1.0",
      "position": {
        "x": 700,
        "y": 80
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Ice_Extent",
      "to_element": "ice_melt"
    },
    {
      "id": "conn-2",
      "from_element": "warming_rate",
      "to_element": "ice_melt"
    },
    {
      "id": "conn-3",
      "from_element": "melt_sensitivity",
      "to_element": "ice_melt"
    }
  ],
  "time_settings": {
    "start": 1979,
    "end": 2100,
    "dt": 1
  },
  "created_at": "2026-01-11T20:04:50.699512Z",
  "updated_at": "2026-01-11T20:04:50.699512Z",
  "source": "https://github.com/SDXorg/PySD-Cookbook",
  "reference": "SDXorg System Dynamics Model Repository"
}

{
  "id": "forest-fire-spread-cli",
  "name": "Humidity",
  "description": "Illustrative forest fire stock-flow model with heuristic wind, fuel and humidity multipliers. Rothermel (1972) is background on surface fire spread; this file does not implement the published reaction-intensity, propagating-flux and heat-sink formulation. Area, perimeter and fuel units, depletion and calibration require review.",
  "stocks": [
    {
      "id": "s1",
      "name": "Unburned_Forest_Ha",
      "initial_value": 10000,
      "equation": "",
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "s2",
      "name": "Active_Fire_Ha",
      "initial_value": 1,
      "equation": "",
      "position": {
        "x": 400,
        "y": 200
      }
    },
    {
      "id": "s3",
      "name": "Burned_Forest_Ha",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 600,
        "y": 200
      }
    },
    {
      "id": "s4",
      "name": "Fuel_Load",
      "initial_value": 20,
      "equation": "",
      "position": {
        "x": 400,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "f1",
      "name": "Fire_Spread",
      "equation": "Spread_Rate * Perimeter_Length",
      "from_stock": "s1",
      "to_stock": "s2",
      "position": {
        "x": 300,
        "y": 200
      }
    },
    {
      "id": "f2",
      "name": "Burnout",
      "equation": "Active_Fire_Ha / Residence_Time",
      "from_stock": "s2",
      "to_stock": "s3",
      "position": {
        "x": 500,
        "y": 200
      }
    },
    {
      "id": "f3",
      "name": "Fuel_Consumption",
      "equation": "Active_Fire_Ha * Consumption_Rate",
      "from_stock": "s4",
      "to_stock": null,
      "position": {
        "x": 500,
        "y": 350
      }
    },
    {
      "id": "f4",
      "name": "Fuel_Accumulation",
      "equation": "Burned_Forest_Ha * Regrowth_Rate",
      "from_stock": null,
      "to_stock": "s4",
      "position": {
        "x": 300,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "v1",
      "name": "Wind_Speed",
      "equation": "10 + 5 * SIN(TIME / 24)",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "v2",
      "name": "Humidity",
      "equation": "30 - 10 * SIN(TIME / 24)",
      "position": {
        "x": 300,
        "y": 100
      }
    },
    {
      "id": "v3",
      "name": "Spread_Rate",
      "equation": "Base_Spread * Wind_Factor * Fuel_Factor * Humidity_Factor",
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "v4",
      "name": "Base_Spread",
      "equation": "0.5",
      "position": {
        "x": 500,
        "y": 100
      }
    },
    {
      "id": "v5",
      "name": "Wind_Factor",
      "equation": "1 + Wind_Speed / 20",
      "position": {
        "x": 200,
        "y": 300
      }
    },
    {
      "id": "v6",
      "name": "Fuel_Factor",
      "equation": "Fuel_Load / 20",
      "position": {
        "x": 400,
        "y": 450
      }
    },
    {
      "id": "v7",
      "name": "Humidity_Factor",
      "equation": "MAX(0.1, 1 - Humidity / 100)",
      "position": {
        "x": 300,
        "y": 300
      }
    },
    {
      "id": "v8",
      "name": "Perimeter_Length",
      "equation": "2 * 3.14159 * SQRT(Active_Fire_Ha / 3.14159)",
      "position": {
        "x": 300,
        "y": 250
      }
    },
    {
      "id": "v9",
      "name": "Residence_Time",
      "equation": "2 / Spread_Rate",
      "position": {
        "x": 500,
        "y": 250
      }
    },
    {
      "id": "v10",
      "name": "Consumption_Rate",
      "equation": "0.5",
      "position": {
        "x": 600,
        "y": 350
      }
    },
    {
      "id": "v11",
      "name": "Regrowth_Rate",
      "equation": "0.001",
      "position": {
        "x": 200,
        "y": 400
      }
    },
    {
      "id": "v12",
      "name": "Fire_Intensity",
      "equation": "Spread_Rate * Fuel_Load * 300",
      "position": {
        "x": 600,
        "y": 100
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Perimeter_Length",
      "to_element": "Fire_Spread"
    },
    {
      "id": "conn-2",
      "from_element": "Spread_Rate",
      "to_element": "Fire_Spread"
    },
    {
      "id": "conn-3",
      "from_element": "Active_Fire_Ha",
      "to_element": "Burnout"
    },
    {
      "id": "conn-4",
      "from_element": "Residence_Time",
      "to_element": "Burnout"
    },
    {
      "id": "conn-5",
      "from_element": "Consumption_Rate",
      "to_element": "Fuel_Consumption"
    },
    {
      "id": "conn-6",
      "from_element": "Active_Fire_Ha",
      "to_element": "Fuel_Consumption"
    },
    {
      "id": "conn-7",
      "from_element": "Burned_Forest_Ha",
      "to_element": "Fuel_Accumulation"
    },
    {
      "id": "conn-8",
      "from_element": "Regrowth_Rate",
      "to_element": "Fuel_Accumulation"
    },
    {
      "id": "conn-9",
      "from_element": "Base_Spread",
      "to_element": "Spread_Rate"
    },
    {
      "id": "conn-10",
      "from_element": "Humidity_Factor",
      "to_element": "Spread_Rate"
    },
    {
      "id": "conn-11",
      "from_element": "Wind_Factor",
      "to_element": "Spread_Rate"
    },
    {
      "id": "conn-12",
      "from_element": "Fuel_Factor",
      "to_element": "Spread_Rate"
    },
    {
      "id": "conn-13",
      "from_element": "Humidity",
      "to_element": "Spread_Rate"
    },
    {
      "id": "conn-14",
      "from_element": "Wind_Speed",
      "to_element": "Wind_Factor"
    },
    {
      "id": "conn-15",
      "from_element": "Fuel_Load",
      "to_element": "Fuel_Factor"
    },
    {
      "id": "conn-16",
      "from_element": "Humidity",
      "to_element": "Humidity_Factor"
    },
    {
      "id": "conn-17",
      "from_element": "Active_Fire_Ha",
      "to_element": "Perimeter_Length"
    },
    {
      "id": "conn-18",
      "from_element": "Spread_Rate",
      "to_element": "Residence_Time"
    },
    {
      "id": "conn-19",
      "from_element": "Spread_Rate",
      "to_element": "Fire_Intensity"
    },
    {
      "id": "conn-20",
      "from_element": "Fuel_Load",
      "to_element": "Fire_Intensity"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 72,
    "dt": 0.25
  },
  "created_at": "2026-01-12T07:26:33.407363+00:00",
  "updated_at": "2026-01-12T07:26:33.407363+00:00",
  "source": "https://doi.org/10.2737/INT-RP-115",
  "reference": "Rothermel, R.C. (1972). A mathematical model for predicting fire spread in wildland fuels. USDA Forest Service Research Paper INT-115. 40 pp. doi:10.2737/INT-RP-115."
}

{
  "id": "global-carbon-cycle-model-cli",
  "name": "Global Carbon Cycle Model",
  "description": "Illustrative global carbon reservoir stock-flow model. Sarmiento and Gruber (2006) is textbook background on ocean biogeochemistry; no particular chapter, equation set, calibrated parameter table or observational validation has been established for this file.",
  "stocks": [
    {
      "id": "stock-atmospheric-carbon",
      "name": "Atmospheric Carbon",
      "initial_value": 589,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-vegetation-carbon",
      "name": "Vegetation Carbon",
      "initial_value": 450,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-soil-carbon",
      "name": "Soil Carbon",
      "initial_value": 1500,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    },
    {
      "id": "stock-surface-ocean-carbon",
      "name": "Surface Ocean Carbon",
      "initial_value": 900,
      "equation": "",
      "position": {
        "x": 750,
        "y": 200
      }
    },
    {
      "id": "stock-deep-ocean-carbon",
      "name": "Deep Ocean Carbon",
      "initial_value": 37100,
      "equation": "",
      "position": {
        "x": 150,
        "y": 350
      }
    },
    {
      "id": "stock-cumulative-anthropogenic-emissions",
      "name": "Cumulative Anthropogenic Emissions",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 350,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-fossil-fuel-emissions",
      "name": "Fossil Fuel Emissions",
      "equation": "Fossil_Emission_Scenario(Time)",
      "from_stock": null,
      "to_stock": "stock-atmospheric-carbon",
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-land-use-change-emissions",
      "name": "Land Use Change Emissions",
      "equation": "Land_Use_Emission_Rate",
      "from_stock": null,
      "to_stock": "stock-atmospheric-carbon",
      "position": {
        "x": 450,
        "y": 200
      }
