      "equation": "0.5",
      "position": {
        "x": 220,
        "y": 80
      }
    },
    {
      "id": "var-total-farms",
      "name": "Total_Farms",
      "equation": "Conventional_Farms + Transitioning_Farms + Sustainable_Farms",
      "position": {
        "x": 360,
        "y": 80
      }
    },
